layer.css:
[data-ryt="pitch"] { color: rgb(241, 245, 249); border-left: 4px solid rgb(49, 65, 88); border-radius: 0px; font-family: ui-sans-serif, system-ui, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; font-size: 16px; font-weight: 500; font-style: italic; line-height: 1.75; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(241, 245, 249); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 16px; transition: all; border-top: none; border-right: none; border-bottom: none }
[data-ryt="footer"] { color: #7b7b7b; font-style: normal; letter-spacing: normal; text-transform: none }
article[data-ryt="rec-card"] { background-color: var(--ryt-surface); border-radius: 8px; box-shadow: rgba(0, 0, 0, 0) 0px 0px 0px 0px, rgba(0, 0, 0, 0) 0px 0px 0px 0px, rgba(0, 0, 0, 0) 0px 0px 0px 0px, rgba(0, 0, 0, 0) 0px 0px 0px 0px, rgba(0, 0, 0, 0.1) 0px 4px 6px -1px, rgba(0, 0, 0, 0.1) 0px 2px 4px -2px; transition: all }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 500; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="hero"] h1 { color: rgb(241, 245, 249); font-family: ui-sans-serif, system-ui, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; font-size: 36px; font-weight: 600; font-style: normal; line-height: 1.111; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(241, 245, 249); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: rgb(226, 232, 240); border-radius: 0px; font-family: ui-sans-serif, system-ui, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; font-size: 16px; font-weight: 500; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(226, 232, 240); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 12px; padding-right: 12px; padding-bottom: 12px; padding-left: 12px; transition: all }
[data-ryt="button"] { color: rgb(144, 161, 185); background-color: rgb(69, 85, 108); border-top: 1px solid rgb(69, 85, 108); border-bottom: 1px solid rgb(69, 85, 108); border-left: 1px solid rgb(69, 85, 108); border-radius: 0px 8px 8px 0px; font-family: ui-sans-serif, system-ui, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; font-weight: 400; font-style: normal; line-height: 1.429; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(144, 161, 185); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 12px; padding-bottom: 0px; padding-left: 12px; transition: all; border-right: none }
[data-ryt="category"], [data-ryt="tags"] li { color: rgb(248, 250, 252); background-color: rgb(0, 96, 69); border-top: 1px solid rgb(0, 96, 69); border-right: 1px solid rgb(0, 96, 69); border-bottom: 1px solid rgb(0, 96, 69); border-left: 1px solid rgb(0, 96, 69); border-radius: 4px; font-family: ui-sans-serif, system-ui, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; font-weight: 400; font-style: normal; line-height: 1.429; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(248, 250, 252); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 4px; padding-right: 8px; padding-bottom: 4px; padding-left: 8px; transition: all }
[data-ryt="review"] { color: var(--ryt-muted); font-family: ui-sans-serif, system-ui, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-muted); font-family: ui-sans-serif, system-ui, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="cover"] { border-radius: 0px }
[data-ryt="rec-card"] [data-ryt="title"] a { color: rgb(226, 232, 240); border-radius: 0px; font-family: ui-sans-serif, system-ui, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; font-weight: 600; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(226, 232, 240); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: rgb(226, 232, 240); border-radius: 0px; font-family: ui-sans-serif, system-ui, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; font-size: 34px; font-weight: 600; font-style: normal; line-height: 1.111; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(226, 232, 240); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
